SELECT i.id,v.id AS version_id,v.version_number,i.kind,v.title,i.status,i.current_version_id,
  NULL AS verification,NULL AS project_status,NULL AS content_json,v.body
FROM knowledge_item i JOIN knowledge_version v
  ON v.owner_id=i.owner_id AND v.item_id=i.id AND v.id=#{versionId}
WHERE i.owner_id=#{owner} AND i.id=#{id}

SELECT 
FROM preparation_item i JOIN preparation_version v
  ON v.owner_id=i.owner_id AND v.item_id=i.id AND v.id=#{versionId}

WHERE i.owner_id=#{owner} AND i.id=#{id}

SELECT 
FROM question q JOIN question_version v
  ON v.owner_id=q.owner_id AND v.question_id=q.id AND v.id=#{versionId}
WHERE q.owner_id=#{owner} AND q.id=#{id}
